const { chromium } = require('playwright');
(async () => { const b = await chromium.launch(); const p = await b.newPage({ viewport: { width: 844, height: 390 } });
  const errs = []; p.on('pageerror', e => errs.push(e.message));
  await p.goto('http://localhost:8080/web/?render=2d'); await p.waitForFunction(() => window.G && G.scene === 'title'); await p.waitForTimeout(300);
  await p.evaluate(() => { G.scene = 'select'; G.sel = 9; }); await p.keyboard.press('Enter'); await p.waitForFunction(() => G.scene === 'play'); await p.waitForTimeout(400);
  const reset = () => p.evaluate(() => { G.run.spawnT = 99; G.aliens = []; G.shots = []; G.hero.inv = 0; G.hero.skillT = 0; G.hero.dash = null; G.hero.meleeCd = 0; G.hero.rangedCd = 0; window.__sw = 0; window.__sh = 0; });
  const st = () => p.evaluate(() => ({ skills: G.run.skillsLeft, inv: G.run.invuln, skillT: +G.hero.skillT.toFixed(2), dash: !!G.hero.dash, swing: !!G.hero.swing, shots: G.shots.length }));
  await p.mouse.move(600, 200); await p.mouse.move(610, 200);
  const click = async (button, hold = 40) => { await p.mouse.down({ button }); await p.waitForTimeout(hold); await p.mouse.up({ button }); };
  await reset(); await click('left'); await p.waitForTimeout(100); console.log('좌클릭 1번 →', JSON.stringify(await st()));
  await p.waitForTimeout(500); await reset(); await click('right'); await p.waitForTimeout(100); console.log('우클릭 1번 →', JSON.stringify(await st()));
  await p.waitForTimeout(500); await reset(); await click('right', 30); await p.waitForTimeout(60); await click('right', 30); await p.waitForTimeout(30); console.log('우클릭 2번 →', JSON.stringify(await st()));
  await p.waitForTimeout(600); await reset(); await p.evaluate(() => { G.hero.swing = null; });
  await p.mouse.down({ button: 'left' }); await p.waitForTimeout(25); await p.mouse.down({ button: 'right' }); await p.waitForTimeout(30); console.log('좌·우 동시 →', JSON.stringify(await st()));
  await p.mouse.up({ button: 'right' }); await p.mouse.up({ button: 'left' });
  await p.waitForTimeout(600); await reset(); await click('left', 30); await p.waitForTimeout(60); await click('left', 30); await p.waitForTimeout(30); console.log('좌클릭 2번(2번 스킬 자리) →', JSON.stringify(await st()));
  await p.waitForTimeout(600); await reset(); await p.keyboard.press('Space'); await p.waitForTimeout(30); console.log('Space →', JSON.stringify(await st()));
  await p.waitForTimeout(600); await reset(); await p.keyboard.press('Space'); await p.waitForTimeout(30); console.log('Space 또 (라운드 2번 다 씀) →', JSON.stringify(await st()));
  await p.mouse.down({ button: 'left' }); await p.waitForTimeout(600); const n = await p.evaluate(() => G.hero.meleeCd); await p.mouse.up({ button: 'left' }); console.log('좌클릭 누르고 있기: 연속 치기 쿨 =', n.toFixed(2));
  console.log('errors:', errs.join(' | ') || 'none'); await b.close(); })();
